-- Part 6 (diversification pass): online MCQ bank (comp_mcq_questions) for pipeline_supervisor
-- ("سرپرست خط لوله"). ZERO rows before this seed (verified via the MCQ count-per-role audit
-- query). ~38 questions, APPROVED and active, spanning TECHNICAL/GENERAL/HSE/SCENARIO/
-- JUDGMENT/PROBLEM_SOLVING/CASE_STUDY, difficulty 1-3, varied stem formats. Domain grounding:
-- API 1104 (pipeline welding), API 1102/ASME B31.4/B31.8 (pipeline crossings/design), API 570,
-- NACE SP0169/SP0502 (cathodic protection / direct assessment), trenching/backfill and
-- hydrostatic-test HSE, right-of-way (ROW) coordination.
-- Same rotation technique as supabase/seed/mcq_questions_seed.sql. Idempotent via
-- (job_role, md5(stem_fa)) unique index.

insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, explanation_fa, standard_ref, approval_status, active)
